// Bilingual Numeral Formatter (English when lang='en', Bengali otherwise)
// Bilingual Numeral Formatter (English when lang='en', Bengali otherwise)
export const toBanglaNum = (num) => {
  if (num === null || num === undefined) return '';
  try {
    const l = typeof window !== 'undefined' && (localStorage.getItem('samity_lang') || localStorage.getItem('hisabkitab_lang') || localStorage.getItem('somiti360_lang'));
    if (l === 'en') {
      const bnDigits = ['০', '১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯'];
      return String(num).replace(/[০-৯]/g, (d) => bnDigits.indexOf(d));
    }
  } catch {}
  const bn = ['০', '১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯'];
  return String(num).replace(/[0-9]/g, (d) => bn[d]);
};


// Member List Excel (.xlsx) Exporter with Unicode Support
export const exportMembersToExcel = (xlsx, members = [], samity = {}) => {
  if (!xlsx || !members.length) return;
  const rows = members.map((m, idx) => ({
    'ক্রমিক': idx + 1,
    'সদস্য কোড / আইডি': m.id || m.memberCode || '',
    'নাম (বাংলা)': m.nameBn || '',
    'নাম (ইংরেজি)': m.nameEn || '',
    'মোবাইল নম্বর': m.mobile || '',
    'বিকল্প মোবাইল': m.altMobile || '',
    'সদস্যপদ শ্রেণি': m.membershipType || 'General',
    'মাসিক সঞ্চয় কিস্তি (টাকা)': Number(m.monthlySubscription) || 500,
    'এনআইডি নম্বর (NID)': m.nidNumber || '',
    'পেশা': m.profession || '',
    'পিতার নাম': m.fatherName || '',
    'বর্তমান ঠিকানা': m.presentAddress || '',
    'স্থায়ী ঠিকানা': m.permanentAddress || '',
    'নমিনীর নাম': m.nomineeName || '',
    'নমিনীর সাথে সম্পর্ক': m.nomineeRelation || '',
    'স্ট্যাটাস': m.status || 'Active',
    'যোগদানের তারিখ': m.joiningDate || ''
  }));

  const worksheet = xlsx.utils.json_to_sheet(rows);
  const workbook = xlsx.utils.book_new();
  xlsx.utils.book_append_sheet(workbook, worksheet, 'সদস্য তালিকা');
  const cleanName = (samity?.nameBn || 'Samity').replace(/[\s/\\?%*:|"<>]/g, '_');
  const filename = `${cleanName}_MemberList_${new Date().toISOString().split('T')[0]}.xlsx`;
  xlsx.writeFile(workbook, filename);
};

export const exportDueDefaultersToExcel = (xlsx, members = [], samity = {}, deposits = [], targetMonth = '', targetYear = 2026) => {
  if (!xlsx || !members.length) return;
  const defaulters = members.map((m, idx) => {
    const status = calculateMemberPaymentStatus(m, samity, deposits, targetMonth, targetYear);
    return {
      'ক্রমিক': idx + 1,
      'সদস্য আইডি': m.id || m.memberCode || '',
      'সদস্যের নাম': m.nameBn || m.nameEn || '',
      'মোবাইল নম্বর': m.mobile || '',
      'সদস্যপদ শ্রেণি': m.membershipType || 'সাধারণ',
      'মাসিক চাঁদা (টাকা)': Number(m.customSubscription || samity.monthlySubscription || 500),
      'জমা দেওয়া হয়েছে': status.paidAmount || 0,
      'বকেয়া পরিমাণ (টাকা)': status.dueAmount || 0,
      'বিলম্ব ফি': status.lateFee || 0,
      'মোট প্রদেয়': status.totalPayable || 0,
      'পেমেন্ট স্ট্যাটাস': status.status === 'paid' ? 'পরিশোধিত' : status.status === 'partially_paid' ? 'আংশিক পরিশোধ' : 'সম্পূর্ণ বকেয়া',
      'মাস ও অর্থবছর': `${targetMonth} ${targetYear}`
    };
  }).filter(r => r['বকেয়া পরিমাণ (টাকা)'] > 0);

  const worksheet = xlsx.utils.json_to_sheet(defaulters);
  const workbook = xlsx.utils.book_new();
  xlsx.utils.book_append_sheet(workbook, worksheet, 'বকেয়া ও ডিউ তালিকা');
  const cleanName = (samity?.nameBn || 'Samity').replace(/[\s/\\?%*:|"<>]/g, '_');
  const filename = `${cleanName}_DueDefaulters_${targetMonth}_${targetYear}.xlsx`;
  xlsx.writeFile(workbook, filename);
};

