  // Official Letterpad Document Writer State (নোটিশ, পত্র ও রেজুলেশন কম্পোজার)
  const [padDocTitle, setPadDocTitle] = useState('জরুরি সাধারণ সভার নোটিশ');
  const [padDocRefNo, setPadDocRefNo] = useState('স্মারক নং: সছস/২০২৬/০১');
  const [padDocDate, setPadDocDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [padDocBody, setPadDocBody] = useState(
    'এতদ্বারা স্বপ্নছোঁয়া সমবায় সমিতির সকল সম্মানিত সাধারণ সদস্যদের অবগতির জন্য জানানো যাচ্ছে যে, আগামী ২৫শে অক্টোবর ২০২৬ তারিখ রোজ শুক্রবার সকাল ১০:০০ ঘটিকায় সমিতির প্রধান কার্যালয়ে এক জরুরি সাধারণ সভা অনুষ্ঠিত হবে।\n\nউক্ত সভায় সমিতির বাৎসরিক অডিট রিপোর্ট উপস্থাপন, নতুন সঞ্চয় স্কিম অনুমোদন এবং কল্যাণ তহবিল পরিচালনা সংক্রান্ত গুরুত্বপূর্ণ সিদ্ধান্ত গ্রহণ করা হবে। সকল সম্মানিত সদস্যকে যথাসময়ে উপস্থিত থাকার জন্য বিনীত অনুরোধ করা হচ্ছে।\n\nধন্যবাদান্তে,\nপরিচালনা পর্ষদ'
  );
  const [padSelectedSignatures, setPadSelectedSignatures] = useState(['sig_president', 'sig_secretary', 'sig_treasurer']);
  const [padWatermarkOpacity, setPadWatermarkOpacity] = useState(0.14);

  // Movable Seal Position state (সিল ড্র্যাগ ও পজিশন কন্ট্রোল)
  const [sealOffset, setSealOffset] = useState({ x: -16, y: -44 });
  const [sealPresetPosition, setSealPresetPosition] = useState('on_sign'); // 'on_sign', 'right', 'left', 'custom'

  // Multi-page splitting logic for A4 letterpad (দীর্ঘ লেখা স্বয়ংক্রিয়ভাবে একাধিক পৃষ্ঠায় ভাগ)
  const padPages = useMemo(() => {
    if (!padDocBody) return [''];
    const paragraphs = padDocBody.split('\n');
    const resultPages = [];
    let currentPage = '';
    const MAX_PAGE_CHARS = 900; // Optimal length per A4 page

    paragraphs.forEach((p) => {
      if ((currentPage + '\n' + p).length > MAX_PAGE_CHARS && currentPage.length > 200) {
        resultPages.push(currentPage.trim());
        currentPage = p;
      } else {
        currentPage = currentPage ? `${currentPage}\n${p}` : p;
      }
    });
    if (currentPage.trim()) {
      resultPages.push(currentPage.trim());
    }
    return resultPages.length > 0 ? resultPages : [''];
  }, [padDocBody]);

  // QR Verification Data URL for Letterpad (স্ক্যানযোগ্য কিউআর কোড)
  const [padQrDataUrl, setPadQrDataUrl] = useState('');

  useEffect(() => {
    let isMounted = true;
    const origin = typeof window !== 'undefined' ? window.location.origin : 'https://hisabkitab360.vercel.app';
    const docHash = `HK360-${Math.abs(((padDocRefNo || 'DOC') + (padDocDate || '2026')).split('').reduce((a, b) => { a = ((a << 5) - a) + b.charCodeAt(0); return a & a; }, 0)).toString(16).toUpperCase()}`;
    const params = new URLSearchParams({
      doc_verify: 'true',
      verify: 'samity_doc',
      ref: padDocRefNo || 'সছস/২০২৬/০১',
      title: padDocTitle || 'অফিসিয়াল নোটিশ ও রেজুলেশন',
      date: padDocDate || new Date().toISOString().split('T')[0],
      samity: currentSamity.nameBn || 'স্বপ্নছোঁয়া সমবায় সমিতি',
      reg: currentSamity.regNo || 'সছস-২০২৪/০৯',
      hash: docHash
    });
    const payload = `${origin}?${params.toString()}`;

    generateQrDataUrl(payload, { width: 140, margin: 1 }).then(url => {
      if (isMounted && url) setPadQrDataUrl(url);
    });
    return () => { isMounted = false; };
  }, [currentSamity.nameBn, currentSamity.regNo, padDocRefNo, padDocTitle, padDocDate]);

  // New Officer Signature & Seal Modal State
