                              borderRadius: '8px',
                              background: isGranted ? 'rgba(16, 185, 129, 0.08)' : 'rgba(255, 255, 255, 0.03)',
                              border: `1px solid ${isGranted ? 'rgba(16, 185, 129, 0.25)' : 'rgba(255, 255, 255, 0.06)'}`,
                              cursor: 'pointer',
                              transition: 'all 0.15s ease'
